/*
    完了にチェックがある
        保存前が空欄なら、保存者を入力
    完了にチェックがないなら
        保存前が入力されてるなら、保存者を消す
*/
Innovator inn = this.getInnovator();
string completeValue = "1";//h4_checkedListの「完了」

var thisId = this.getID();
var saveUser = inn.getUserID();

//完了チェックを見て判定
if(this.getProperty("h4_checked","") == completeValue)
{
    //完了者が入ってないなら入れる
    this.setProperty("h4_completed_by",saveUser);
}


return this;
